function init(){setupTabs(),setupThemeToggle(),setupBookmark(),setupScrollAnimations(),setupJourneyIntegration()}function setupTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>{e.classList.remove("active"),e.setAttribute("hidden","")}),n.classList.add("active"),n.setAttribute("aria-selected","true");const o=document.getElementById(n.dataset.tab);o.classList.add("active"),o.removeAttribute("hidden")})})}function setupThemeToggle(){const e=document.getElementById("theme-toggle");e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const t=document.body.classList.contains("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"☀️":"🌙"}),"light"===localStorage.getItem("theme")&&(document.body.classList.add("light-theme"),e.textContent="☀️")}function setupBookmark(){const e=document.getElementById("bookmark-btn"),t="art-thangka",n=()=>{e.textContent=window.Journey&&window.Journey.isSaved(t)?"✅ Saved to Journey":"🔖 Bookmark to My Journey"};n(),e.addEventListener("click",()=>{window.Journey&&(window.Journey.toggle({id:t,explorerPage:"frontend/thangka-painting-explorer/index.html",title:"Thangka Painting",thumbnail:"https://placehold.co/100/d4af37/fff",category:"art"}),n())})}let observer;function setupScrollAnimations(){"IntersectionObserver"in window&&(observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1}),document.querySelectorAll(".animate-on-scroll").forEach(e=>observer.observe(e)))}function setupJourneyIntegration(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("frontend/thangka-painting-explorer/index.html",[{id:"art-thangka",title:"Thangka Painting",description:"Sacred Tibetan Buddhist scroll paintings.",link:"#"}])}document.addEventListener("DOMContentLoaded",init);